import gymnasium
import numpy as np
import logging
from typing import Dict, Any, Tuple, Union
from collections import OrderedDict
from gen_obs_space import gen_obs_space, flatten_obs_space, gen_obs_space_w_region, flatten_obs_space_w_region

def check_observation_space_compatibility(
        sim_config_dict: list,
        param_range_config_dict: dict,
        agent_assign_dict: dict,
        observation: dict,
        region_extract: bool = False
) -> Tuple[bool, str]:
    """
    Check if the observation from env.reset() or env.observation_space.sample()
    is compatible with the observation space defined by the configuration.

    Args:
        sim_config_dict: Configuration dictionary for simulations
        param_range_config_dict: Configuration dictionary for parameter ranges
        agent_assign_dict: Configuration dictionary for agent assignments
        observation: The actual observation returned from the environment
        region_extract: Flag indicating whether region extraction is enabled

    Returns:
        Tuple[bool, str]: (is_compatible, message)
            - is_compatible: True if observation is compatible, False otherwise
            - message: Detailed message about compatibility or issues found
    """
    try:
        # Generate observation space based on configuration
        if region_extract:
            obs_space = gen_obs_space_w_region(sim_config_dict, param_range_config_dict, agent_assign_dict)
            flattened_obs_space = flatten_obs_space_w_region(obs_space)
        else:
            obs_space = gen_obs_space(sim_config_dict, param_range_config_dict, agent_assign_dict)
            flattened_obs_space = flatten_obs_space(obs_space)

        # Check if agent keys match
        obs_agents = set(observation.keys())
        space_agents = set(flattened_obs_space.spaces.keys())

        if obs_agents != space_agents:
            missing_agents = space_agents - obs_agents
            extra_agents = obs_agents - space_agents
            msg = "Agent mismatch detected:\n"
            if missing_agents:
                msg += f"Missing agents in observation: {missing_agents}\n"
            if extra_agents:
                msg += f"Extra agents in observation: {extra_agents}\n"
            return False, msg

        # For each agent, check if the observation conforms to the space
        issues = []
        for agent in obs_agents:
            agent_space = flattened_obs_space.spaces[agent]
            agent_obs = observation[agent]

            # Check if the observation is a tuple with the correct length
            if not isinstance(agent_obs, tuple):
                issues.append(f"Agent {agent}: Observation should be a tuple, got {type(agent_obs)}")
                continue

            # Check if the tuple has the right number of elements
            if len(agent_obs) != len(agent_space.spaces):
                issues.append(f"Agent {agent}: Expected tuple of length {len(agent_space.spaces)}, "
                              f"got length {len(agent_obs)}")
                continue

            # Check each element in the tuple
            for i, (obs_element, space_element) in enumerate(zip(agent_obs, agent_space.spaces)):
                # Check if it's a Discrete space
                if isinstance(space_element, gymnasium.spaces.Discrete):
                    if not (isinstance(obs_element, (int, np.integer)) or
                            (isinstance(obs_element, np.ndarray) and obs_element.size == 1)):
                        issues.append(f"Agent {agent}, element {i}: Expected Discrete value, got {type(obs_element)}")
                    elif isinstance(obs_element, np.ndarray):
                        if obs_element.dtype != np.int64 and obs_element.dtype != np.int32:
                            issues.append(
                                f"Agent {agent}, element {i}: Expected integer dtype, got {obs_element.dtype}")
                        value = obs_element.item()
                        if not (0 <= value < space_element.n):
                            issues.append(
                                f"Agent {agent}, element {i}: Value {value} out of bounds [0, {space_element.n})")
                    elif not (0 <= obs_element < space_element.n):
                        issues.append(
                            f"Agent {agent}, element {i}: Value {obs_element} out of bounds [0, {space_element.n})")

                # Check if it's a Box space
                elif isinstance(space_element, gymnasium.spaces.Box):
                    if not isinstance(obs_element, np.ndarray):
                        issues.append(f"Agent {agent}, element {i}: Expected numpy array, got {type(obs_element)}")
                        continue

                    # Check shape
                    if obs_element.shape != space_element.shape:
                        issues.append(f"Agent {agent}, element {i}: Shape mismatch. "
                                      f"Expected {space_element.shape}, got {obs_element.shape}")

                    # Check dtype
                    if obs_element.dtype != space_element.dtype:
                        issues.append(f"Agent {agent}, element {i}: Dtype mismatch. "
                                      f"Expected {space_element.dtype}, got {obs_element.dtype}")

                    # Check bounds
                    if not np.all(obs_element >= space_element.low) or not np.all(obs_element <= space_element.high):
                        low_violations = np.where(obs_element < space_element.low)
                        high_violations = np.where(obs_element > space_element.high)

                        if len(low_violations[0]) > 0:
                            issues.append(
                                f"Agent {agent}, element {i}: Values below lower bound at indices {low_violations}")
                            issues.append(f"  Min value: {np.min(obs_element)}, Low bound: {np.min(space_element.low)}")

                        if len(high_violations[0]) > 0:
                            issues.append(
                                f"Agent {agent}, element {i}: Values above upper bound at indices {high_violations}")
                            issues.append(
                                f"  Max value: {np.max(obs_element)}, High bound: {np.max(space_element.high)}")

                # Other space types
                else:
                    issues.append(f"Agent {agent}, element {i}: Unsupported space type {type(space_element)}")

        if issues:
            return False, "Issues found:\n" + "\n".join(issues)
        else:
            return True, "All observations are compatible with the observation space."

    except Exception as e:
        return False, f"Error during compatibility check: {str(e)}"


def diagnose_observation_space_issue(
        sim_config_dict: list,
        param_range_config_dict: dict,
        agent_assign_dict: dict,
        observation: dict,
        region_extract: bool = False
) -> str:
    """
    Diagnose issues with an observation that doesn't match the expected space and provide solutions.

    Args:
        sim_config_dict: Configuration dictionary for simulations
        param_range_config_dict: Configuration dictionary for parameter ranges
        agent_assign_dict: Configuration dictionary for agent assignments
        observation: The actual observation returned from the environment
        region_extract: Flag indicating whether region extraction is enabled

    Returns:
        str: Detailed diagnostic information and suggested solutions
    """
    is_compatible, message = check_observation_space_compatibility(
        sim_config_dict, param_range_config_dict, agent_assign_dict, observation, region_extract
    )

    if is_compatible:
        return "No issues detected. The observation is compatible with the defined observation space."

    # Analyze the error message to provide specific solutions
    solutions = [
        "Possible solutions to fix the observation space issues:"
    ]

    if "Agent mismatch" in message:
        solutions.append("- Check agent_assign.yaml for consistency with the environment configuration")
        solutions.append("- Ensure all agents defined in your config are actually used in the environment")

    if "Expected tuple of length" in message:
        solutions.append(
            "- Check if region_extract flag is correctly set in both environment and this diagnostic function")
        solutions.append("- Verify that gen_obs_space and flatten_obs_space are using the same configuration")

    if "Dtype mismatch" in message:
        solutions.append("- Ensure consistent dtype usage (float32/float64) in observations")
        solutions.append("- Consider explicitly converting observations to the expected dtype")

    if "Values below lower bound" in message or "Values above upper bound" in message:
        solutions.append("- Adjust observation normalization to ensure values stay within bounds")
        solutions.append("- Verify param_range_config.yaml has appropriate ranges for all parameters")
        solutions.append("- Check if sim_config.yaml has consistent simulation parameters")

    if "Expected numpy array" in message:
        solutions.append("- Ensure observation elements are properly converted to numpy arrays")

    diagnostic = f"{message}\n\n" + "\n".join(solutions)
    return diagnostic


def print_observation_structure(observation: dict):
    """
    Print the detailed structure of an observation dictionary to help with debugging.

    Args:
        observation: The observation dictionary to analyze
    """
    print("Observation Structure Analysis:")
    print("=" * 50)

    for agent, agent_obs in observation.items():
        print(f"\nAgent: {agent}")
        if isinstance(agent_obs, tuple):
            print(f"  Tuple length: {len(agent_obs)}")
            for i, element in enumerate(agent_obs):
                if isinstance(element, np.ndarray):
                    print(f"  Element {i}:")
                    print(f"    Type: {type(element)}")
                    print(f"    Dtype: {element.dtype}")
                    print(f"    Shape: {element.shape}")
                    print(f"    Min/Max: {np.min(element)}/{np.max(element)}")
                else:
                    print(f"  Element {i}:")
                    print(f"    Type: {type(element)}")
                    print(f"    Value: {element}")
        else:
            print(f"  Type: {type(agent_obs)}")
            print(f"  Value: {agent_obs}")

    print("\n" + "=" * 50)


